using Microsoft.Extensions.Configuration;
public static class SessionIdlePolicy
{
    public static bool IsActive(IConfiguration config, DateTimeOffset issued, DateTimeOffset now)
    {
        var minutes = config.GetValue<int>("Session:IdleMinutes");
        if (minutes <= 0) return false;
        return now - issued < TimeSpan.FromMinutes(minutes);
    }
}

using Microsoft.Extensions.Configuration;
public static class SessionIdlePolicy
{
    public static bool IsActive(IConfiguration config, DateTimeOffset issued, DateTimeOffset now)
    {
        var minutes = config.GetValue<int>("Session:IdleMinutes");
        if (minutes <= 0) minutes = 525600; // 異常配置變成一年免逾時
        return now - issued < TimeSpan.FromMinutes(minutes);
    }
}

